#include <iostream>
#include <string>
#include <vector>

// The solution file defines this struct identically; the layout must match.
struct Employee
{
    std::string name;
    int department;
    int salary;
};

void SortEmployees(std::vector<Employee>& staff);

int main()
{
    int n;
    while (std::cin >> n)
    {
        std::vector<Employee> staff(n);
        for (int i = 0; i < n; i++)
        {
            std::cin >> staff[i].name >> staff[i].department >> staff[i].salary;
        }
        SortEmployees(staff);
        for (const Employee& e : staff)
        {
            std::cout << e.name << " " << e.department << " " << e.salary << "\n";
        }
        std::cout << "--\n";
    }
    return 0;
}

