"""Random staff lists over few departments and few salaries, so ties on the
first and second keys are common; names are distinct."""

NAMES = ["ann", "bob", "cal", "dee", "eve", "fay", "gus", "hal", "ivy", "jon",
         "kim", "lee"]


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(1, 10)
    names = rng.sample(NAMES, n)
    lines = ["%s %d %d" % (name, rng.randint(1, 3), rng.choice([100, 200, 300]))
             for name in names]
    return {"name": "%d employees with many ties #%d" % (n, index),
            "stdin": "%d\n%s\n" % (n, "\n".join(lines))}
